    private function computePersediaanTotalCache($rekening, $cabangID, $selectedPeriode, $selectedThn, $selectedBln, $selectedDateFull)
    {
        $periode = "forever";
        $params = array();
        $where = array();

        if ($selectedPeriode == "tahunan") {
            $periode = "tahunan";
            $where[] = "thn = ?";
            $params[] = (int)$selectedThn;
        }
        elseif ($selectedPeriode == "bulanan" || $selectedPeriode == "harian") {
            $periode = "bulanan";
            $where[] = "thn = ?";
            $params[] = (int)$selectedThn;
            $where[] = "bln <= ?";
            $params[] = (int)$selectedBln;
            if ($selectedPeriode == "harian" && $selectedDateFull != "") {
                $day = (int)date("d", strtotime($selectedDateFull));
                $where[] = "tgl <= ?";
                $params[] = $day;
            }
        }

        $baseWhere = "periode = ? AND rekening = ? AND cabang_id = ?";
        $paramsBase = array($periode, $rekening, (int)$cabangID);
        $whereSql = $baseWhere;
        if (sizeof($where) > 0) {
            $whereSql .= " AND " . implode(" AND ", $where);
        }

        $snapshotSql = "";
        $paramsSnapshot = array();
        if ($periode == "bulanan") {
            $snapshotSql = " AND id IN (
                SELECT MAX(t_last.id)
                FROM _rek_pembantu_produk_cache t_last
                WHERE t_last.periode = 'bulanan'
                    AND t_last.rekening = ?
                    AND t_last.cabang_id = ?
                    AND t_last.thn = ?
                    AND t_last.bln <= ?
                GROUP BY t_last.extern_id, t_last.gudang_id
            )";
            $paramsSnapshot = array($rekening, (int)$cabangID, (int)$selectedThn, (int)$selectedBln);
        }

        $sql = "SELECT SUM(debet) AS total_debet
            FROM _rek_pembantu_produk_cache
            WHERE " . $whereSql . $snapshotSql;

        $paramsAll = array_merge($paramsBase, $params, $paramsSnapshot);
        $row = $this->db->query($sql, $paramsAll)->row();
        if ($row && isset($row->total_debet)) {
            return (float)$row->total_debet;
        }
        return 0;
    }

    public function viewBalances_l1_header($relName, $rekName)
    {
        $defPosition = detectRekDefaultPosition($rekName);
        $cfgAll = $this->config->item('accountBalanceProfiles');
        $cfg = (is_array($cfgAll) && isset($cfgAll[$relName])) ? $cfgAll[$relName] : array();
        $header = (isset($cfg['header']) && is_array($cfg['header'])) ? $cfg['header'] : array();
        $headerFields = array();

        foreach ($header as $kky => $label) {
            if (strpos($kky, ':') !== false) {
                $kky = preg_replace('/:.*/', '' . $defPosition, $kky);
            }
            $headerFields[$kky] = $label;
        }

        return $headerFields;
    }

