    private function resolveUangMukaPivotDim($dim, $fallback)
    {
        $maps = array(
            "supplier" => array(
                "key" => "supplier",
                "id_field" => "extern_id",
                "name_field" => "extern_nama",
                "label" => "Supplier",
            ),
            "reference" => array(
                "key" => "reference",
                "id_field" => "extern2_id",
                "name_field" => "extern2_nama",
                "label" => "Reference/PO",
            ),
            "segment" => array(
                "key" => "segment",
                "id_field" => "extern3_id",
                "name_field" => "extern3_nama",
                "label" => "Segmen",
            ),
            "cabang" => array(
                "key" => "cabang",
                "id_field" => "cabang_id",
                "name_field" => "cabang_nama",
                "label" => "Cabang",
            ),
            "doc" => array(
                "key" => "doc",
                "id_field" => "extern5_id",
                "name_field" => "extern5_nama",
                "label" => "Dokumen",
            ),
            "jenis" => array(
                "key" => "jenis",
                "id_field" => "jenis",
                "name_field" => "jenis",
                "label" => "Jenis",
            ),
            "none" => array(
                "key" => "none",
                "id_field" => "",
                "name_field" => "",
                "label" => "-",
            ),
        );

        $dim = strtolower(trim((string)$dim));
        $fallback = strtolower(trim((string)$fallback));
        if (isset($maps[$dim])) {
            return $maps[$dim];
        }
        if (isset($maps[$fallback])) {
            return $maps[$fallback];
        }
        return $maps["supplier"];
    }

    private function buildUangMukaPivotData($opts = array())
    {
        $rekening = isset($opts['rekening']) ? trim((string)$opts['rekening']) : "";
        $cabangID = isset($opts['cabang_id']) ? (int)$opts['cabang_id'] : 0;
        $selectedPeriode = isset($opts['selected_periode']) ? strtolower(trim((string)$opts['selected_periode'])) : "full";
        $selectedThn = isset($opts['selected_thn']) ? (int)$opts['selected_thn'] : (int)date("Y");
        $selectedBln = isset($opts['selected_bln']) ? (int)$opts['selected_bln'] : (int)date("m");
        $selectedDate = isset($opts['selected_date']) ? trim((string)$opts['selected_date']) : date("Y-m-d");
        $asOfDate = isset($opts['as_of_date']) ? trim((string)$opts['as_of_date']) : date("Y-m-d");
        $q = isset($opts['q']) ? trim((string)$opts['q']) : "";
        $sourceTable = isset($opts['source_table']) ? trim((string)$opts['source_table']) : "_rek_pembantu_uang_muka_reference_cache";
        $metric = isset($opts['metric']) ? strtolower(trim((string)$opts['metric'])) : "saldo_open";
        $rowDim = isset($opts['row_dim']) ? trim((string)$opts['row_dim']) : "supplier";
        $colDim = isset($opts['col_dim']) ? trim((string)$opts['col_dim']) : "none";

        if (!preg_match('/^\d{4}\-\d{2}\-\d{2}$/', $selectedDate)) {
            $selectedDate = date("Y-m-d");
        }
        if (!preg_match('/^\d{4}\-\d{2}\-\d{2}$/', $asOfDate)) {
            $asOfDate = date("Y-m-d");
        }

        if ($sourceTable == "" || !$this->db->table_exists($sourceTable)) {
            return array(
                "row_label" => "Supplier",
                "col_label" => "-",
                "metric_label" => "Saldo Open (IDR)",
                "items" => array(),
                "headerFields" => array(
                    "pivot_row" => "SUPPLIER",
                    "metric_value" => "Saldo Open (IDR)",
                    "saldo_open" => "Saldo Open (IDR)",
                    "ref_count" => "Jumlah Referensi",
                    "avg_age" => "Aging Rata-rata",
                    "max_age" => "Aging Maksimum",
                    "stamp" => "Timestamp",
                ),
                "row_count" => 0,
                "col_count" => 0,
            );
        }

        $allowedMetricLabels = array(
            "saldo_open" => "Saldo Open (IDR)",
            "ref_count" => "Jumlah Referensi",
            "avg_age" => "Aging Rata-rata (Hari)",
            "max_age" => "Aging Maksimum (Hari)",
        );
        if (!isset($allowedMetricLabels[$metric])) {
            $metric = "saldo_open";
        }

        $rowMap = $this->resolveUangMukaPivotDim($rowDim, "supplier");
        $colMap = $this->resolveUangMukaPivotDim($colDim, "none");
        if ($rowMap["key"] == "none") {
            $rowMap = $this->resolveUangMukaPivotDim("supplier", "supplier");
        }
        if ($colMap["key"] == $rowMap["key"]) {
            $colMap = $this->resolveUangMukaPivotDim("none", "none");
        }

        $asOfEsc = $this->db->escape($asOfDate);
        $ageExpr = "CASE WHEN DATEDIFF($asOfEsc, IFNULL(fulldate, DATE(dtime))) > 0 "
            . "THEN DATEDIFF($asOfEsc, IFNULL(fulldate, DATE(dtime))) ELSE 0 END";
        $saldoExpr = "SUM(IFNULL(debet,0)-IFNULL(kredit,0))";
        $refCountExpr = "COUNT(DISTINCT CASE WHEN IFNULL(extern2_id,0)>0 THEN extern2_id END)";
        $avgAgeExpr = "ROUND(AVG($ageExpr),0)";
        $maxAgeExpr = "MAX($ageExpr)";

        $rowIdExpr = "IFNULL(" . $rowMap["id_field"] . ",0)";
        $rowNameExpr = "TRIM(IFNULL(" . $rowMap["name_field"] . ",'-'))";
        $rowSelect = $rowIdExpr . " AS row_id, " . $rowNameExpr . " AS row_name";
        $metricSelect = $saldoExpr . " AS saldo_open, "
            . $refCountExpr . " AS ref_count, "
            . $avgAgeExpr . " AS avg_age, "
            . $maxAgeExpr . " AS max_age";

        $queryPivotRows = function ($withCabangFilter, $fallbackAllCabang) use ($sourceTable, $rekening, $cabangID, $selectedPeriode, $selectedThn, $selectedBln, $selectedDate, $q, $colMap, $rowSelect, $metricSelect, $rowMap) {
            $this->db->reset_query();
            $this->db->from($sourceTable);
            if ($rekening != "") {
                $this->db->where("rekening", $rekening);
            }
            if ($withCabangFilter) {
                $this->db->where("cabang_id", $cabangID);
            }
            elseif ($fallbackAllCabang) {
                $this->db->where("cabang_id >", 0);
            }

            switch ($selectedPeriode) {
                case "tahunan":
                    $this->db->where("periode", "tahunan");
                    $this->db->where("thn", $selectedThn);
                    break;
                case "bulanan":
                    $this->db->where("periode", "bulanan");
                    $this->db->where("thn", $selectedThn);
                    $this->db->where("bln <=", $selectedBln);
                    break;
                case "harian":
                    $this->db->where("periode", "harian");
                    $this->db->where("fulldate <=", $selectedDate);
                    break;
                case "full":
                default:
                    $this->db->where("periode", "forever");
                    break;
            }

            if ($q != "") {
                $this->db->group_start();
                $this->db->like("extern_nama", $q);
                $this->db->or_like("extern2_nama", $q);
                $this->db->or_like("extern3_nama", $q);
                $this->db->or_like("extern5_nama", $q);
                $this->db->or_like("jenis", $q);
                $this->db->group_end();
            }

            if ($colMap["key"] == "none") {
                $this->db->select($rowSelect, false);
                $this->db->select($metricSelect, false);
                $this->db->group_by($rowMap["id_field"]);
                $this->db->group_by($rowMap["name_field"]);
            }
            else {
                $colIdExpr = "IFNULL(" . $colMap["id_field"] . ",0)";
                $colNameExpr = "TRIM(IFNULL(" . $colMap["name_field"] . ",'-'))";
                $this->db->select($rowSelect, false);
                $this->db->select($colIdExpr . " AS col_id, " . $colNameExpr . " AS col_name", false);
                $this->db->select($metricSelect, false);
                $this->db->group_by($rowMap["id_field"]);
                $this->db->group_by($rowMap["name_field"]);
                $this->db->group_by($colMap["id_field"]);
                $this->db->group_by($colMap["name_field"]);
            }
            return $this->db->get()->result_array();
        };

        $rows = $queryPivotRows(true, false);
        if ($cabangID == -1 && sizeof($rows) == 0) {
            // fallback mode pusat: jika cache cabang -1 belum ada, ambil akumulasi cabang aktif
            $rows = $queryPivotRows(false, true);
        }

        $metricResolver = function ($row) use ($metric) {
            switch ($metric) {
                case "ref_count":
                    return isset($row['ref_count']) ? (float)$row['ref_count'] : 0;
                case "avg_age":
                    return isset($row['avg_age']) ? (float)$row['avg_age'] : 0;
                case "max_age":
                    return isset($row['max_age']) ? (float)$row['max_age'] : 0;
                case "saldo_open":
                default:
                    return isset($row['saldo_open']) ? (float)$row['saldo_open'] : 0;
            }
        };

        $metricLabel = isset($allowedMetricLabels[$metric]) ? $allowedMetricLabels[$metric] : $allowedMetricLabels["saldo_open"];
        $headerFields = array();
        $items = array();

        if ($colMap["key"] == "none") {
            foreach ($rows as $row) {
                $rowID = isset($row['row_id']) ? (int)$row['row_id'] : 0;
                $rowName = isset($row['row_name']) ? trim((string)$row['row_name']) : "-";
                if ($rowName == "") {
                    $rowName = "-";
                }
                $metricValue = $metricResolver($row);
                $saldoOpen = isset($row['saldo_open']) ? (float)$row['saldo_open'] : 0;
                $refCount = isset($row['ref_count']) ? (int)$row['ref_count'] : 0;
                $avgAge = isset($row['avg_age']) ? (int)$row['avg_age'] : 0;
                $maxAge = isset($row['max_age']) ? (int)$row['max_age'] : 0;

                $items[] = array(
                    "pId" => ($rowID > 0) ? $rowID : (sizeof($items) + 1),
                    "link" => "#",
                    "link_main" => array(),
                    "pivot_row" => $rowName,
                    "metric_value" => $metricValue,
                    "saldo_open" => $saldoOpen,
                    "ref_count" => $refCount,
                    "avg_age" => $avgAge,
                    "max_age" => $maxAge,
                    "stamp" => dtimeNow("ymd-His"),
                );
            }

            usort($items, function ($left, $right) {
                $l = isset($left['metric_value']) ? (float)$left['metric_value'] : 0;
                $r = isset($right['metric_value']) ? (float)$right['metric_value'] : 0;
                if ($l == $r) {
                    return 0;
                }
                return ($l < $r) ? 1 : -1;
            });

            $headerFields = array(
                "pivot_row" => strtoupper($rowMap["label"]),
                "metric_value" => $metricLabel,
                "saldo_open" => "Saldo Open (IDR)",
                "ref_count" => "Jumlah Referensi",
                "avg_age" => "Aging Rata-rata",
                "max_age" => "Aging Maksimum",
                "stamp" => "Timestamp",
            );
        }
        else {
            $rowData = array();
            $colMeta = array();
            $colTotals = array();

            foreach ($rows as $row) {
                $rowID = isset($row['row_id']) ? (int)$row['row_id'] : 0;
                $rowName = isset($row['row_name']) ? trim((string)$row['row_name']) : "-";
                if ($rowName == "") {
                    $rowName = "-";
                }
                $colID = isset($row['col_id']) ? trim((string)$row['col_id']) : "0";
                $colName = isset($row['col_name']) ? trim((string)$row['col_name']) : "-";
                if ($colName == "") {
                    $colName = "-";
                }
                $colKey = "c_" . md5($colID . "|" . $colName);

                if (!isset($rowData[$rowName])) {
                    $rowData[$rowName] = array(
                        "pId" => ($rowID > 0) ? $rowID : (sizeof($rowData) + 1),
                        "link" => "#",
                        "link_main" => array(),
                        "pivot_row" => $rowName,
                        "_total" => 0,
                        "_max" => 0,
                    );
                }
                if (!isset($colMeta[$colKey])) {
                    $labelTmp = $colName;
                    if ($colID != "0" && $colID != "") {
                        $labelTmp .= " (" . $colID . ")";
                    }
                    $colMeta[$colKey] = $labelTmp;
                    $colTotals[$colKey] = 0;
                }

                $metricValue = $metricResolver($row);
                $rowData[$rowName][$colKey] = isset($rowData[$rowName][$colKey]) ? ((float)$rowData[$rowName][$colKey] + (float)$metricValue) : (float)$metricValue;
                $rowData[$rowName]["_total"] += (float)$metricValue;
                if ((float)$metricValue > (float)$rowData[$rowName]["_max"]) {
                    $rowData[$rowName]["_max"] = (float)$metricValue;
                }
                $colTotals[$colKey] += (float)$metricValue;
            }

            uksort($colMeta, function ($leftKey, $rightKey) use ($colTotals, $colMeta) {
                $lv = isset($colTotals[$leftKey]) ? (float)$colTotals[$leftKey] : 0;
                $rv = isset($colTotals[$rightKey]) ? (float)$colTotals[$rightKey] : 0;
                if ($lv == $rv) {
                    $leftLabel = isset($colMeta[$leftKey]) ? (string)$colMeta[$leftKey] : (string)$leftKey;
                    $rightLabel = isset($colMeta[$rightKey]) ? (string)$colMeta[$rightKey] : (string)$rightKey;
                    return strnatcasecmp($leftLabel, $rightLabel);
                }
                return ($lv < $rv) ? 1 : -1;
            });

            foreach ($rowData as $rowName => $rowSpec) {
                foreach ($colMeta as $colKey => $colLabel) {
                    if (!isset($rowSpec[$colKey])) {
                        $rowSpec[$colKey] = 0;
                    }
                }
                if ($metric == "avg_age" || $metric == "max_age") {
                    $rowSpec["metric_total"] = isset($rowSpec["_max"]) ? (float)$rowSpec["_max"] : 0;
                }
                else {
                    $rowSpec["metric_total"] = isset($rowSpec["_total"]) ? (float)$rowSpec["_total"] : 0;
                }
                unset($rowSpec["_total"]);
                unset($rowSpec["_max"]);
                $rowSpec["stamp"] = dtimeNow("ymd-His");
                $items[] = $rowSpec;
            }

            usort($items, function ($left, $right) {
                $l = isset($left['metric_total']) ? (float)$left['metric_total'] : 0;
                $r = isset($right['metric_total']) ? (float)$right['metric_total'] : 0;
                if ($l == $r) {
                    return 0;
                }
                return ($l < $r) ? 1 : -1;
            });

            $headerFields = array(
                "pivot_row" => strtoupper($rowMap["label"]),
            );
            foreach ($colMeta as $colKey => $colLabel) {
                $headerFields[$colKey] = $colLabel;
            }
            $headerFields["metric_total"] = $metricLabel . " (Total)";
            $headerFields["stamp"] = "Timestamp";
        }

        return array(
            "row_label" => $rowMap["label"],
            "col_label" => $colMap["label"],
            "metric_label" => $metricLabel,
            "items" => $items,
            "headerFields" => $headerFields,
            "row_count" => sizeof($items),
            "col_count" => ($colMap["key"] == "none") ? 0 : sizeof($headerFields),
        );
    }

    private function buildUangMukaHierarchySummary($opts = array())
    {
        $accounts = isset($opts['accounts']) && is_array($opts['accounts']) ? $opts['accounts'] : array();
        $cabangID = isset($opts['cabang_id']) ? (int)$opts['cabang_id'] : 0;
        $selectedPeriode = isset($opts['selected_periode']) ? strtolower(trim((string)$opts['selected_periode'])) : "full";
        $selectedThn = isset($opts['selected_thn']) ? (int)$opts['selected_thn'] : (int)date("Y");
        $selectedBln = isset($opts['selected_bln']) ? (int)$opts['selected_bln'] : (int)date("m");
        $selectedDate = isset($opts['selected_date']) ? trim((string)$opts['selected_date']) : date("Y-m-d");
        $sourceTable = isset($opts['source_table']) ? trim((string)$opts['source_table']) : "_rek_pembantu_uang_muka_reference_cache";

        $summary = array();
        $totals = array(
            "all" => 0,
            "supplier_count" => 0,
        );

        if (sizeof($accounts) == 0) {
            return array(
                "summary" => $summary,
                "totals" => $totals,
            );
        }

        $accountKeys = array_keys($accounts);
        foreach ($accountKeys as $accountKey) {
            $summary[$accountKey] = array(
                "saldo" => 0,
                "count" => 0,
            );
        }

        if ($sourceTable == "" || !$this->db->table_exists($sourceTable)) {
            return array(
                "summary" => $summary,
                "totals" => $totals,
            );
        }

        $applyHierarchyWhere = function ($withCabangFilter, $fallbackAllCabang) use ($cabangID, $accountKeys, $selectedPeriode, $selectedThn, $selectedBln, $selectedDate) {
            if ($withCabangFilter) {
                $this->db->where("cabang_id", $cabangID);
            }
            elseif ($fallbackAllCabang) {
                $this->db->where("cabang_id >", 0);
            }
            $this->db->where_in("rekening", $accountKeys);

            switch ($selectedPeriode) {
                case "tahunan":
                    $this->db->where("periode", "tahunan");
                    $this->db->where("thn", $selectedThn);
                    break;
                case "bulanan":
                    $this->db->where("periode", "bulanan");
                    $this->db->where("thn", $selectedThn);
                    $this->db->where("bln <=", $selectedBln);
                    break;
                case "harian":
                    $this->db->where("periode", "harian");
                    $this->db->where("fulldate <=", $selectedDate);
                    break;
                case "full":
                default:
                    $this->db->where("periode", "forever");
                    break;
            }
        };

        $queryByRekening = function ($withCabangFilter, $fallbackAllCabang) use ($sourceTable, $applyHierarchyWhere) {
            $this->db->reset_query();
            $this->db->select("rekening", false);
            $this->db->select("SUM(IFNULL(debet,0)-IFNULL(kredit,0)) AS saldo", false);
            $this->db->select("COUNT(DISTINCT CASE WHEN IFNULL(extern_id,0)>0 THEN extern_id END) AS supplier_count", false);
            $this->db->from($sourceTable);
            $applyHierarchyWhere($withCabangFilter, $fallbackAllCabang);
            $this->db->group_by("rekening");
            return $this->db->get()->result_array();
        };

        $queryDistinctSupplierCount = function ($withCabangFilter, $fallbackAllCabang) use ($sourceTable, $applyHierarchyWhere) {
            $this->db->reset_query();
            $this->db->select("COUNT(DISTINCT CASE WHEN IFNULL(extern_id,0)>0 THEN extern_id END) AS supplier_count_total", false);
            $this->db->from($sourceTable);
            $applyHierarchyWhere($withCabangFilter, $fallbackAllCabang);
            $row = $this->db->get()->row_array();
            return isset($row["supplier_count_total"]) ? (int)$row["supplier_count_total"] : 0;
        };

        $fallbackAllCabang = false;
        $rows = $queryByRekening(true, false);
        if ($cabangID == -1 && sizeof($rows) == 0) {
            // fallback mode pusat: jika cache cabang -1 belum tersedia, pakai akumulasi cabang aktif
            $rows = $queryByRekening(false, true);
            $fallbackAllCabang = true;
        }

        if (sizeof($rows) > 0) {
            foreach ($rows as $row) {
                $rek = isset($row["rekening"]) ? trim((string)$row["rekening"]) : "";
                if ($rek == "" || !isset($summary[$rek])) {
                    continue;
                }
                $saldo = isset($row["saldo"]) ? (float)$row["saldo"] : 0;
                $supplierCount = isset($row["supplier_count"]) ? (int)$row["supplier_count"] : 0;
                $summary[$rek]["saldo"] = $saldo;
                $summary[$rek]["count"] = $supplierCount;
                $totals["all"] += $saldo;
            }
        }

        $totals["supplier_count"] = $queryDistinctSupplierCount(!$fallbackAllCabang, $fallbackAllCabang);

        return array(
            "summary" => $summary,
            "totals" => $totals,
        );
    }

    public function viewBalances_l1()
    {

        $dateLogstart = microtime(true);

        $relName = $this->uri->segment(3);
        $rekName = urldecode($this->uri->segment(4));
        $defPosition = detectRekDefaultPosition($rekName);
        $wo = (isset($_GET["wo"]) && is_numeric($_GET["wo"])) ? (int)$_GET["wo"] : 1;
        // dikasih default 1 dulu supaya tampil gudang workorder-nya...

        $end1 = microtime(true);
        $start1 = $end1 - $dateLogstart;
        //        cekHere(__LINE__);
        //        showlast_query("biru");
        //        cekHitam("durasi:" . $start1);
        //        cekBiru(count($defPosition));
        $dateSelected = false;
        $balConfig = isset($this->config->item('accountBalanceColumns')[$relName]) ? $this->config->item('accountBalanceColumns')[$relName] : array();
        $accountBalanceColumnsAll = $this->config->item('accountBalanceColumns');
        $accountBalanceColumnsAll = is_array($accountBalanceColumnsAll) ? $accountBalanceColumnsAll : array();
        $accountFilters = isset($this->config->item('accountBalanceColumns')[$relName]['viewFilters']) ? $this->config->item('accountBalanceColumns')[$relName]['viewFilters'] : array();
        $accountRekDetailAdditional = isset($this->config->item('accountRekDetailAdditional')[$rekName]) ? $this->config->item('accountRekDetailAdditional')[$rekName] : array();
        $accountBalanceAdditionalColumns = isset($this->config->item('accountBalanceAdditionalColumns')[$rekName]) ? $this->config->item('accountBalanceAdditionalColumns')[$rekName] : array();
        $accountChilds = ($this->config->item('accountChilds') != NULL) ? $this->config->item('accountChilds') : array();
        $accountSubChilds = ($this->config->item('accountSubChilds') != NULL) ? $this->config->item('accountSubChilds') : array();
        $accountBalanceLocker = isset($this->config->item('accountBalanceColumLocker')[$relName]) ? $this->config->item('accountBalanceColumLocker')[$relName] : array();
        $accountSuperSubChilds = ($this->config->item('accountSuperSubChilds') != NULL) ? $this->config->item('accountSuperSubChilds') : array();
        $accountBalanceAdvanceColumns = array();
        $accountBalanceAdvanceConfigs = $this->config->item('accountBalanceAdvanceColumns');
        $accountBalanceAdvanceConfigs = is_array($accountBalanceAdvanceConfigs) ? $accountBalanceAdvanceConfigs : array();
        $accountBalanceAdvanceProfiles = $this->config->item('accountBalanceAdvanceProfiles');
        $accountBalanceAdvanceProfiles = is_array($accountBalanceAdvanceProfiles) ? $accountBalanceAdvanceProfiles : array();
        $accountBalanceAdvanceAccountMap = $this->config->item('accountBalanceAdvanceAccountMap');
        $accountBalanceAdvanceAccountMap = is_array($accountBalanceAdvanceAccountMap) ? $accountBalanceAdvanceAccountMap : array();

        $normalizeAdvanceKey = function ($value) {
            $value = strtolower(trim((string)$value));
            if ($value == "") {
                return "";
            }
            $value = preg_replace('/\s+/', ' ', $value);
            return $value;
        };

        $advanceMapNorm = array();
        if (sizeof($accountBalanceAdvanceAccountMap) > 0) {
            foreach ($accountBalanceAdvanceAccountMap as $mapKey => $mapProfile) {
                $mapKeyNorm = $normalizeAdvanceKey($mapKey);
                if ($mapKeyNorm != "") {
                    $advanceMapNorm[$mapKeyNorm] = $mapProfile;
                }
            }
        }

        $rekAliases = is_array($this->rekAlias) ? $this->rekAlias : array();
        $rekAliasAdvanceRaw = isset($rekAliases[$rekName]) ? (string)$rekAliases[$rekName] : "";
        $rekAliasAdvance = $normalizeAdvanceKey(($rekAliasAdvanceRaw != "") ? $rekAliasAdvanceRaw : $rekName);
        $advanceCandidates = array(
            $normalizeAdvanceKey($rekName),
            $rekAliasAdvance,
        );
        $advanceCandidates = array_values(array_unique(array_filter($advanceCandidates)));
        $isTaxHierarchyAccount = false;
        $taxHierarchyConfigAdvance = $this->config->item("accountHierarchyPajakPKP");
        $taxHierarchyConfigAdvance = is_array($taxHierarchyConfigAdvance) ? $taxHierarchyConfigAdvance : array();
        $taxHierarchyCategoriesAdvance = isset($taxHierarchyConfigAdvance["categories"]) && is_array($taxHierarchyConfigAdvance["categories"]) ? $taxHierarchyConfigAdvance["categories"] : array();
        if (sizeof($taxHierarchyCategoriesAdvance) > 0) {
            $taxAccountCandidates = array();
            foreach ($taxHierarchyCategoriesAdvance as $catSpecAdvance) {
                $taxAccountsAdvance = isset($catSpecAdvance["accounts"]) && is_array($catSpecAdvance["accounts"]) ? $catSpecAdvance["accounts"] : array();
                foreach ($taxAccountsAdvance as $taxKeyAdvance => $taxMetaAdvanceRaw) {
                    $taxMetaAdvance = is_array($taxMetaAdvanceRaw) ? $taxMetaAdvanceRaw : array();
                    $taxAccountCandidates[] = $normalizeAdvanceKey($taxKeyAdvance);
                    if (isset($taxMetaAdvance["route_rekening"])) {
                        $taxAccountCandidates[] = $normalizeAdvanceKey($taxMetaAdvance["route_rekening"]);
                    }
                    if (isset($taxMetaAdvance["aliases"]) && is_array($taxMetaAdvance["aliases"])) {
                        foreach ($taxMetaAdvance["aliases"] as $taxAliasAdvance) {
                            $taxAccountCandidates[] = $normalizeAdvanceKey($taxAliasAdvance);
                        }
                    }
                }
            }
            $taxAccountCandidates = array_values(array_unique(array_filter($taxAccountCandidates)));
            if (sizeof($taxAccountCandidates) > 0 && sizeof($advanceCandidates) > 0) {
                foreach ($advanceCandidates as $advanceCandidateCheck) {
                    if (in_array($advanceCandidateCheck, $taxAccountCandidates)) {
                        $isTaxHierarchyAccount = true;
                        break;
                    }
                }
            }
        }

        $resolvedAdvanceProfile = "";
        if (sizeof($advanceCandidates) > 0 && sizeof($advanceMapNorm) > 0) {
            foreach ($advanceCandidates as $advanceCandidate) {
                if (!isset($advanceMapNorm[$advanceCandidate])) {
                    continue;
                }
                $resolvedAdvanceProfile = trim((string)$advanceMapNorm[$advanceCandidate]);
                if ($resolvedAdvanceProfile == "") {
                    continue;
                }
                if (isset($accountBalanceAdvanceProfiles[$resolvedAdvanceProfile]) && is_array($accountBalanceAdvanceProfiles[$resolvedAdvanceProfile])) {
                    $accountBalanceAdvanceColumns = $accountBalanceAdvanceProfiles[$resolvedAdvanceProfile];
                    break;
                }
                // kompatibel jika map menunjuk key legacy
                if (isset($accountBalanceAdvanceConfigs[$resolvedAdvanceProfile]) && is_array($accountBalanceAdvanceConfigs[$resolvedAdvanceProfile])) {
                    $accountBalanceAdvanceColumns = $accountBalanceAdvanceConfigs[$resolvedAdvanceProfile];
                    break;
                }
            }
        }

        // fallback legacy agar koding lama tetap berjalan
        if (sizeof($accountBalanceAdvanceColumns) == 0 && isset($accountBalanceAdvanceConfigs[$rekName])) {
            $accountBalanceAdvanceColumns = $accountBalanceAdvanceConfigs[$rekName];
        }
        if (sizeof($accountBalanceAdvanceColumns) == 0 && $rekAliasAdvance != "" && isset($accountBalanceAdvanceConfigs[$rekAliasAdvance])) {
            $accountBalanceAdvanceColumns = $accountBalanceAdvanceConfigs[$rekAliasAdvance];
        }
        if (sizeof($accountBalanceAdvanceColumns) == 0 && $relName == "RekeningPembantuSupplier" && !$isTaxHierarchyAccount) {
            if (isset($accountBalanceAdvanceConfigs["hutang dagang"])) {
                $accountBalanceAdvanceColumns = $accountBalanceAdvanceConfigs["hutang dagang"];
            }
            elseif (isset($accountBalanceAdvanceConfigs["hutang usaha"])) {
                $accountBalanceAdvanceColumns = $accountBalanceAdvanceConfigs["hutang usaha"];
            }
        }
        $accountSuperSubChildsNonRekening = ($this->config->item('accountSuperSubChildsNonRekening') != NULL) ? $this->config->item('accountSuperSubChildsNonRekening') : array();
        $customLink = isset($balConfig["customLink"]) ? $balConfig["customLink"] : array();//rencana untuk link custom link pergudang
        $q = $this->input->get('q', TRUE);
        $q = is_string($q) ? trim($q) : "";
        if (strlen($q) > 100) {
            $q = substr($q, 0, 100);
        }
        $sortBy = $this->input->get('sortBy', TRUE);
        $sortBy = is_string($sortBy) ? trim($sortBy) : "";
        $allowedSortBy = array(
            "extern_nama",
            "extern_id",
            "debet",
            "kredit",
            "qty_debet",
            "qty_kredit",
        );
        if (!in_array($sortBy, $allowedSortBy)) {
            $sortBy = "extern_nama";
        }
        $sortMode = strtoupper((string)$this->input->get('sortMode', TRUE));
        $sortMode = in_array($sortMode, array("ASC", "DESC")) ? $sortMode : "ASC";
        $merekFilterRaw = $this->input->get('merek', TRUE);
        $merekFilterRaw = is_string($merekFilterRaw) ? trim($merekFilterRaw) : "";
        if (strlen($merekFilterRaw) > 80) {
            $merekFilterRaw = substr($merekFilterRaw, 0, 80);
        }
        $merekFilterNorm = strtolower($merekFilterRaw);
        $persediaanBrandViewModeRaw = strtolower(trim((string)$this->input->get('brand_view', TRUE)));
        $persediaanBrandViewMode = in_array($persediaanBrandViewModeRaw, array("chip", "dropdown")) ? $persediaanBrandViewModeRaw : "chip";
        $brandPanelAjax = $this->input->get('brand_panel_ajax', TRUE);
        $brandPanelAjax = (is_numeric($brandPanelAjax) && (int)$brandPanelAjax === 1) ? 1 : 0;

        $getExternID = $this->input->get('ext_id', TRUE);
        $getExternID = (is_numeric($getExternID) && (int)$getExternID > 0) ? (int)$getExternID : NULL;
        $getExtern2ID = $this->input->get('ext2_id', TRUE);
        $getExtern2ID = (is_numeric($getExtern2ID) && (int)$getExtern2ID > 0) ? (int)$getExtern2ID : NULL;
        $getMainExtern2ID = $this->input->get('main_ext2_id', TRUE);
        $getMainExtern2ID = (is_numeric($getMainExtern2ID) && (int)$getMainExtern2ID > 0) ? (int)$getMainExtern2ID : NULL;
        $normalizeJenisFilter = function ($rawJenis) {
            $jenisRawList = array();
            if (is_array($rawJenis)) {
                $jenisRawList = $rawJenis;
            }
            else {
                $rawJenis = trim((string)$rawJenis);
                if ($rawJenis != "") {
                    $jenisRawList = explode(",", $rawJenis);
                }
            }

            $jenisValues = array();
            foreach ($jenisRawList as $jenisRaw) {
                if (is_array($jenisRaw)) {
                    continue;
                }
                $jenisVal = trim((string)$jenisRaw);
                if ($jenisVal == "") {
                    continue;
                }
                if (!preg_match('/^[a-zA-Z0-9_\-]+$/', $jenisVal)) {
                    continue;
                }
                $jenisValues[] = $jenisVal;
            }
            return array_values(array_unique($jenisValues));
        };
        $buildJenisFilterKey = function ($jenisValues) use ($normalizeJenisFilter) {
            $jenisValues = $normalizeJenisFilter($jenisValues);
            if (sizeof($jenisValues) == 0) {
                return "";
            }
            sort($jenisValues);
            return implode("|", $jenisValues);
        };
        $getJenisFilters = $normalizeJenisFilter($this->input->get('jenis', TRUE));
        $getJenisFilterCsv = (sizeof($getJenisFilters) > 0) ? implode(",", $getJenisFilters) : "";
        $getJenisFilterKey = $buildJenisFilterKey($getJenisFilters);
        $allowJenisFilterOnMainQuery = (sizeof($getJenisFilters) > 0 && ($relName == "RekeningPembantuCustomer" || $relName == "RekeningPembantuCustomerDetail"));
        $blobExtRaw = isset($_GET['blob_ext']) ? $_GET['blob_ext'] : "";
        $blob_ext = strlen($blobExtRaw) ? blobDecode($blobExtRaw) : NULL;

        $cabangReq = $this->input->get('o', TRUE);
