            // kompatibel legacy: o=-1 dipakai sebagai konteks khusus (mis. pusat/akumulasi)
            if ($cabangReq > 0 || $cabangReq == -1) {
                $cabangID = $cabangReq;
            }
        }
        $gudangReq = $this->input->get('w', TRUE);
        $selectedGudangID = (is_numeric($gudangReq) && (int)$gudangReq > 0) ? (int)$gudangReq : NULL;

        $currentYear = (int)date("Y");
        $currentMonth = (int)date("m");
        $currentDate = date("Y-m-d");

        $legacyDate = $this->input->get('date', TRUE);
        $legacyDate = is_string($legacyDate) ? trim($legacyDate) : "";

        $selectedPeriode = strtolower((string)$this->input->get('periode', TRUE));
        $selectedPeriode = trim($selectedPeriode);
        if ($selectedPeriode == "") {
            if ($legacyDate != "" && preg_match('/^\d{4}\-\d{2}\-\d{2}$/', $legacyDate)) {
                $selectedPeriode = "harian";
            }
            elseif ($legacyDate != "" && preg_match('/^\d{4}\-\d{2}$/', $legacyDate)) {
                $selectedPeriode = "bulanan";
            }
            elseif ($this->input->get('thn', TRUE) !== NULL && $this->input->get('thn', TRUE) !== "") {
                $selectedPeriode = "tahunan";
            }
            else {
                $selectedPeriode = "full";
            }
        }
        $allowedPeriode = array("full", "tahunan", "bulanan", "harian");
        if (!in_array($selectedPeriode, $allowedPeriode)) {
            $selectedPeriode = "full";
        }

        $selectedThn = $this->input->get('thn', TRUE);
        $selectedThn = (is_numeric($selectedThn) && (int)$selectedThn >= 2000 && (int)$selectedThn <= 2100) ? (int)$selectedThn : $currentYear;
        $selectedBln = $this->input->get('bln', TRUE);
        $selectedBln = (is_numeric($selectedBln) && (int)$selectedBln >= 1 && (int)$selectedBln <= 12) ? (int)$selectedBln : $currentMonth;

        if ($legacyDate != "" && preg_match('/^\d{4}\-\d{2}$/', $legacyDate)) {
            $legacyDateArr = explode("-", $legacyDate);
            $legacyThn = (int)$legacyDateArr[0];
            $legacyBln = (int)$legacyDateArr[1];
            if ($legacyThn >= 2000 && $legacyThn <= 2100 && $legacyBln >= 1 && $legacyBln <= 12) {
                $selectedThn = $legacyThn;
                $selectedBln = $legacyBln;
                $selectedPeriode = "bulanan";
            }
        }
        $selectedDate = $currentDate;
        if ($legacyDate != "" && preg_match('/^\d{4}\-\d{2}\-\d{2}$/', $legacyDate)) {
            $selectedDateTs = strtotime($legacyDate);
            if ($selectedDateTs !== FALSE) {
                $selectedDate = date("Y-m-d", $selectedDateTs);
            }
        }
        if ($selectedDate > $currentDate) {
            $selectedDate = $currentDate;
        }
        if ($selectedPeriode == "full") {
            $selectedThn = $currentYear;
            $selectedBln = $currentMonth;
        }
        if ($selectedPeriode == "harian") {
            $selectedThn = (int)date("Y", strtotime($selectedDate));
            $selectedBln = (int)date("m", strtotime($selectedDate));
        }
        $selectedPeriodEndDate = $currentDate;
        switch ($selectedPeriode) {
            case "tahunan":
                $selectedPeriodEndDate = sprintf("%04d-12-31", $selectedThn);
                break;
            case "bulanan":
                $selectedPeriodEndDate = date("Y-m-t", mktime(0, 0, 0, $selectedBln, 1, $selectedThn));
                break;
            case "harian":
                $selectedPeriodEndDate = $selectedDate;
                break;
            case "full":
            default:
                $selectedPeriodEndDate = $currentDate;
                break;
        }
        if ($selectedPeriodEndDate > $currentDate) {
