        $uangMukaHierarchyConfig = is_array($uangMukaHierarchyConfig) ? $uangMukaHierarchyConfig : array();
        $uangMukaHierarchyAccounts = isset($uangMukaHierarchyConfig["accounts"]) && is_array($uangMukaHierarchyConfig["accounts"]) ? $uangMukaHierarchyConfig["accounts"] : array();
        $uangMukaPivotConfig = isset($uangMukaHierarchyConfig["pivot"]) && is_array($uangMukaHierarchyConfig["pivot"]) ? $uangMukaHierarchyConfig["pivot"] : array();
        $uangMukaCurrentCode = "";
