        );
        $uangMukaPivotMetricLabels = array(
            "saldo_open" => "Saldo Open (IDR)",
            "ref_count" => "Jumlah Referensi",
            "avg_age" => "Aging Rata-rata (Hari)",
            "max_age" => "Aging Maksimum (Hari)",
        );

        $uangMukaDefaultMode = isset($uangMukaHierarchyConfig["default_mode"]) ? strtolower(trim((string)$uangMukaHierarchyConfig["default_mode"])) : "hierarchy";
        if (!isset($uangMukaModeOptions[$uangMukaDefaultMode])) {
            $uangMukaDefaultMode = "hierarchy";
        }
        $uangMukaDefaultRowDim = isset($uangMukaPivotConfig["default_row_dim"]) ? strtolower(trim((string)$uangMukaPivotConfig["default_row_dim"])) : "supplier";
        $uangMukaDefaultColDim = isset($uangMukaPivotConfig["default_col_dim"]) ? strtolower(trim((string)$uangMukaPivotConfig["default_col_dim"])) : "none";
        $uangMukaDefaultMetric = isset($uangMukaPivotConfig["default_metric"]) ? strtolower(trim((string)$uangMukaPivotConfig["default_metric"])) : "saldo_open";

        $uangMukaAllowedRowDims = isset($uangMukaPivotConfig["allowed_row_dims"]) && is_array($uangMukaPivotConfig["allowed_row_dims"]) ? $uangMukaPivotConfig["allowed_row_dims"] : array("supplier");
        $uangMukaAllowedColDims = isset($uangMukaPivotConfig["allowed_col_dims"]) && is_array($uangMukaPivotConfig["allowed_col_dims"]) ? $uangMukaPivotConfig["allowed_col_dims"] : array("none");
        $uangMukaAllowedMetrics = isset($uangMukaPivotConfig["allowed_metrics"]) && is_array($uangMukaPivotConfig["allowed_metrics"]) ? $uangMukaPivotConfig["allowed_metrics"] : array("saldo_open");

