            $uangMukaPivotColDim = $uangMukaDefaultColDim;
            $uangMukaPivotMetric = $uangMukaDefaultMetric;
        }

        $uangMukaPivotRowOptions = array();
        foreach ($uangMukaAllowedRowDims as $dimKey) {
            $dimKey = trim((string)$dimKey);
            if ($dimKey == "") {
                continue;
            }
            $uangMukaPivotRowOptions[$dimKey] = isset($uangMukaPivotDimLabels[$dimKey]) ? $uangMukaPivotDimLabels[$dimKey] : ucwords(str_replace("_", " ", $dimKey));
        }
        $uangMukaPivotColOptions = array();
        foreach ($uangMukaAllowedColDims as $dimKey) {
            $dimKey = trim((string)$dimKey);
            if ($dimKey == "") {
                continue;
            }
            $uangMukaPivotColOptions[$dimKey] = isset($uangMukaPivotDimLabels[$dimKey]) ? $uangMukaPivotDimLabels[$dimKey] : ucwords(str_replace("_", " ", $dimKey));
        }
        $uangMukaPivotMetricOptions = array();
        foreach ($uangMukaAllowedMetrics as $metricKey) {
            $metricKey = trim((string)$metricKey);
            if ($metricKey == "") {
                continue;
            }
            $uangMukaPivotMetricOptions[$metricKey] = isset($uangMukaPivotMetricLabels[$metricKey]) ? $uangMukaPivotMetricLabels[$metricKey] : ucwords(str_replace("_", " ", $metricKey));
        }

