                                $catParentRekening = $resolvedParentRekening;
                            }
                            if ($catParentRekening == "") {
                                continue;
                            }

                            $catCandidates = isset($catSpec["sub_rekening_candidates"]) && is_array($catSpec["sub_rekening_candidates"]) ? $catSpec["sub_rekening_candidates"] : array();
                            $normalizedCandidates = array();
                            foreach ($catCandidates as $catCandidateRaw) {
                                $catCandidate = trim((string)$catCandidateRaw);
                                if ($catCandidate != "") {
                                    $normalizedCandidates[] = $catCandidate;
                                }
                            }
                            $normalizedCandidates = array_values(array_unique($normalizedCandidates));

                            $catRouteSubRekening = isset($catSpec["route_sub_rekening"]) ? trim((string)$catSpec["route_sub_rekening"]) : "";
                            if ($catRouteSubRekening == "" && sizeof($normalizedCandidates) > 0) {
                                $catRouteSubRekening = $normalizedCandidates[0];
                            }
                            $catJenisCandidates = isset($catSpec["jenis_candidates"]) && is_array($catSpec["jenis_candidates"]) ? $normalizeJenisFilter($catSpec["jenis_candidates"]) : array();
                            $catJenisExclude = isset($catSpec["jenis_exclude"]) && is_array($catSpec["jenis_exclude"]) ? $normalizeJenisFilter($catSpec["jenis_exclude"]) : array();
                            $catRouteJenisCandidates = isset($catSpec["route_jenis_candidates"]) && is_array($catSpec["route_jenis_candidates"]) ? $normalizeJenisFilter($catSpec["route_jenis_candidates"]) : array();
                            if (sizeof($catRouteJenisCandidates) == 0 && sizeof($catJenisCandidates) > 0) {
                                $catRouteJenisCandidates = $catJenisCandidates;
                            }
                            $catRouteJenisKey = $buildJenisFilterKey($catRouteJenisCandidates);

                            $catRouteEnabled = isset($catSpec["route_enabled"]) ? (bool)$catSpec["route_enabled"] : (sizeof($normalizedCandidates) > 0);
                            if ($catStatus == "planned") {
                                $catRouteEnabled = false;
                            }

                            $catAliases = array($catKey, $catParentRekening);
                            if ($catRouteSubRekening != "") {
                                $catAliases[] = $catRouteSubRekening;
                            }
                            foreach ($normalizedCandidates as $catCandidate) {
                                $catAliases[] = $catCandidate;
                            }
                            $catAliases = array_values(array_unique($catAliases));

                            $hkResolvedAccounts[$catKey] = array(
                                "label" => $catLabel,
                                "note" => $catNote,
                                "aliases" => $catAliases,
                                "route_rekening" => $catParentRekening,
                                "query_rekening" => $catParentRekening,
                                "sub_rekening_candidates" => $normalizedCandidates,
                                "route_ext2_id" => $catRouteSubRekening,
                                "jenis_candidates" => $catJenisCandidates,
                                "jenis_exclude" => $catJenisExclude,
                                "route_jenis_candidates" => $catRouteJenisCandidates,
                                "status" => $catStatus,
                                "route_enabled" => $catRouteEnabled,
                                "route_rel" => "",
                                "summary_rel" => "",
                            );

                            if ($currentSubRekening != "" && in_array($currentSubRekening, $normalizedCandidates)) {
                                $isJenisMatch = false;
                                if (sizeof($catRouteJenisCandidates) > 0) {
                                    $isJenisMatch = ($getJenisFilterKey != "" && $getJenisFilterKey == $catRouteJenisKey);
                                }
                                else {
                                    $isJenisMatch = ($getJenisFilterKey == "");
                                }
                                if ($isJenisMatch) {
                                    $hutangHierarchyCurrentCode = $catKey;
                                }
                            }
                        }
                    }
                }

                if (sizeof($hkResolvedAccounts) > 0) {
                    $hutangHierarchyAccounts = $hkResolvedAccounts;
                    $hutangHierarchyEntityLabel = "customer";
                    $hutangHierarchyRelTarget = "RekeningPembantuCustomer";
                    if ($relName == "RekeningPembantuCustomerDetail") {
                        $hutangHierarchyRelTarget = "RekeningPembantuCustomerDetail";
                    }
                    elseif ($relName == "RekeningPembantuCustomerValas") {
                        $hutangHierarchyRelTarget = "RekeningPembantuCustomerValas";
                    }
                }
            }
        }
        $isHutangKonsumenHierarchyActive = in_array($hutangHierarchyRelTarget, array("RekeningPembantuCustomer", "RekeningPembantuCustomerDetail", "RekeningPembantuCustomerValas"));
        if ($hutangHierarchyCurrentCode == "" && ($relName == "RekeningPembantuSupplier" || $isHutangBankRel || $isHutangGajiRel || $isHutangSahamRel || $isHutangBungaRel || $isHutangPphRel || ($isHutangKonsumenRel && $isHutangKonsumenHierarchyActive))) {
            $accountAliases = fetchAccountStructureAlias();
            foreach ($hutangHierarchyAccounts as $rekCode => $rekMeta) {
                $rekAliases = isset($rekMeta["aliases"]) && is_array($rekMeta["aliases"]) ? $rekMeta["aliases"] : array($rekCode);
                if (!in_array($rekCode, $rekAliases)) {
                    $rekAliases[] = $rekCode;
                }
                if (isset($accountAliases[$rekCode]) && trim((string)$accountAliases[$rekCode]) != "") {
                    $rekAliases[] = $accountAliases[$rekCode];
                }
                foreach ($rekAliases as $rekAlias) {
                    if (strtolower(trim((string)$rekAlias)) == $rekNameNorm) {
                        $hutangHierarchyCurrentCode = $rekCode;
                        break 2;
                    }
                }
            }
        }
        if ($hutangHierarchyCurrentCode == "" && $hutangHierarchyUseCategoryCard && sizeof($hutangHierarchyAccounts) > 0) {
            foreach ($hutangHierarchyAccounts as $rekCode => $rekMeta) {
                $rekStatus = isset($rekMeta["status"]) ? strtolower(trim((string)$rekMeta["status"])) : "active";
                if ($rekStatus != "planned") {
                    $hutangHierarchyCurrentCode = $rekCode;
                    break;
                }
            }
            if ($hutangHierarchyCurrentCode == "") {
                $hkKeys = array_keys($hutangHierarchyAccounts);
                if (sizeof($hkKeys) > 0) {
                    $hutangHierarchyCurrentCode = $hkKeys[0];
                }
            }
        }
        if ($hutangHierarchyCurrentCode != "") {
            $showHutangHierarchy = true;
            $hutangHierarchyCurrent = $hutangHierarchyCurrentCode;
            $hutangHierarchyQuery = $pageQuery;
            if ($q != "") {
                $hutangHierarchyQuery["q"] = $q;
            }
            if ($isHutangKonsumenRel && $isHutangKonsumenHierarchyActive) {
                unset($hutangHierarchyQuery["ext2_id"]);
                unset($hutangHierarchyQuery["main_ext2_id"]);
            }
            foreach ($hutangHierarchyAccounts as $rekCode => $rekMeta) {
                $routeRekening = isset($rekMeta["route_rekening"]) ? trim((string)$rekMeta["route_rekening"]) : trim((string)$rekCode);
                if ($routeRekening == "") {
                    $routeRekening = trim((string)$rekCode);
                }
                $queryRekening = isset($rekMeta["query_rekening"]) ? trim((string)$rekMeta["query_rekening"]) : $routeRekening;
                if ($queryRekening == "") {
                    $queryRekening = $routeRekening;
                }
                $routeEnabled = isset($rekMeta["route_enabled"]) ? (bool)$rekMeta["route_enabled"] : true;
                $routeExt2ID = isset($rekMeta["route_ext2_id"]) ? trim((string)$rekMeta["route_ext2_id"]) : "";
                $rekStatus = isset($rekMeta["status"]) ? strtolower(trim((string)$rekMeta["status"])) : "active";
                $summaryCandidates = isset($rekMeta["sub_rekening_candidates"]) && is_array($rekMeta["sub_rekening_candidates"]) ? $rekMeta["sub_rekening_candidates"] : array();
                $summaryJenisCandidates = isset($rekMeta["jenis_candidates"]) && is_array($rekMeta["jenis_candidates"]) ? $normalizeJenisFilter($rekMeta["jenis_candidates"]) : array();
                $summaryJenisExclude = isset($rekMeta["jenis_exclude"]) && is_array($rekMeta["jenis_exclude"]) ? $normalizeJenisFilter($rekMeta["jenis_exclude"]) : array();
                $routeJenisCandidates = isset($rekMeta["route_jenis_candidates"]) && is_array($rekMeta["route_jenis_candidates"]) ? $normalizeJenisFilter($rekMeta["route_jenis_candidates"]) : array();
                $routeRel = isset($rekMeta["route_rel"]) ? trim((string)$rekMeta["route_rel"]) : "";
                $summaryRel = isset($rekMeta["summary_rel"]) ? trim((string)$rekMeta["summary_rel"]) : "";
                if ($hutangHierarchyUseCategoryCard) {
                    if ($routeRel == "") {
                        $routeRel = $hutangHierarchyRelTarget;
                    }
                    if ($summaryRel == "") {
                        $summaryRel = $hutangHierarchyRelTarget;
                    }
                }
                else {
                    if ($routeRel == "") {
                        $routeRel = $resolveHierarchyRelByCandidates(array($routeRekening, $queryRekening, $rekCode), $hutangHierarchyRelTarget);
                    }
                    if ($summaryRel == "") {
                        $summaryRel = $resolveHierarchyRelByCandidates(array($queryRekening, $routeRekening, $rekCode), $routeRel);
                    }
                }
                if (!$isComRelationUsable($routeRel)) {
                    $routeRel = $hutangHierarchyRelTarget;
                }
                if (!$isComRelationUsable($summaryRel)) {
                    $summaryRel = $routeRel;
                }

                $routeQuery = $hutangHierarchyQuery;
                unset($routeQuery["jenis"]);
                if ($routeExt2ID != "") {
                    $routeQuery["ext2_id"] = $routeExt2ID;
                    $routeQuery["main_ext2_id"] = $routeExt2ID;
                }
                if (sizeof($routeJenisCandidates) > 0) {
                    $routeQuery["jenis"] = implode(",", $routeJenisCandidates);
                }
                $routeUrl = "#";
                if ($routeEnabled) {
                    $routeUrl = base_url() . get_class($this) . "/" . $this->uri->segment(2) . "/" . $routeRel . "/" . rawurlencode($routeRekening) . "?" . http_build_query($routeQuery);
                }
                $hutangHierarchyLinks[$rekCode] = array(
                    "label" => $rekMeta["label"],
                    "note" => $rekMeta["note"],
                    "url" => $routeUrl,
                    "status" => $rekStatus,
                    "route_enabled" => $routeEnabled,
                    "query_rekening" => $queryRekening,
                    "sub_rekening_candidates" => $summaryCandidates,
                    "route_ext2_id" => $routeExt2ID,
                    "jenis_candidates" => $summaryJenisCandidates,
                    "jenis_exclude" => $summaryJenisExclude,
                    "summary_rel" => $summaryRel,
                );
            }
            if ($hutangHierarchyUseCategoryCard) {
                $hutangHierarchyNote = "Mode hutang ke konsumen aktif: kategori kewajiban ditampilkan dengan status active/planned.";
                if ($getJenisFilterCsv != "") {
                    $hutangHierarchyNote .= " Filter jenis aktif: " . $getJenisFilterCsv . ".";
                }
            }
            elseif ($isHutangGajiRel) {
                $hutangHierarchyNote = "Mode hutang gaji aktif: saldo ditampilkan per akun dengan total hutang gaji.";
            }
            elseif ($isHutangSahamRel) {
                $hutangHierarchyNote = "Mode hutang pemegang saham aktif: saldo ditampilkan per akun dengan total kewajiban.";
            }
            elseif ($isHutangBungaRel) {
                $hutangHierarchyNote = "Mode hutang biaya bunga aktif: saldo ditampilkan per akun dengan total biaya bunga.";
            }
            elseif ($isHutangPphRel) {
                $hutangHierarchyNote = "Mode hutang PPh aktif: saldo ditampilkan per akun dengan total kewajiban pajak.";
            }
            else {
                $hutangHierarchyNote = "Mode hutang aktif: dimensi akun x " . $hutangHierarchyEntityLabel . " x cabang ditampilkan untuk analisa pivot.";
            }
        }

        $showTaxHierarchy = false;
        $taxHierarchyCurrent = "";
        $taxHierarchyLinks = array();
        $taxHierarchyNote = "";
        $taxHierarchyTotals = array(
            "all" => 0,
            "entity_count" => 0,
            "cabang_count" => 0,
            "active_account_count" => 0,
            "planned_account_count" => 0,
            "category_totals" => array(),
        );
        $taxHierarchyConfig = $this->config->item("accountHierarchyPajakPKP");
        $taxHierarchyConfig = is_array($taxHierarchyConfig) ? $taxHierarchyConfig : array();
        // single source of truth ada di config heAccounting.php -> accountHierarchyPajakPKP
        $taxHierarchyEnabled = isset($taxHierarchyConfig["enabled"]) ? (bool)$taxHierarchyConfig["enabled"] : false;
        $taxHierarchyCategories = isset($taxHierarchyConfig["categories"]) && is_array($taxHierarchyConfig["categories"]) ? $taxHierarchyConfig["categories"] : array();
        if (sizeof($taxHierarchyCategories) == 0) {
            $taxHierarchyEnabled = false;
        }

        $accountRelLookup = array();
        if (is_array($accountSubChilds) && sizeof($accountSubChilds) > 0) {
            foreach ($accountSubChilds as $accKeyLookup => $relLookup) {
                $accKeyNorm = strtolower(trim((string)$accKeyLookup));
                if ($accKeyNorm == "") {
                    continue;
                }
                $accountRelLookup[$accKeyNorm] = trim((string)$relLookup);
            }
        }
        if (is_array($accountChilds) && sizeof($accountChilds) > 0) {
            foreach ($accountChilds as $accKeyLookup => $relLookup) {
                $accKeyNorm = strtolower(trim((string)$accKeyLookup));
                if ($accKeyNorm == "") {
                    continue;
                }
                if (!isset($accountRelLookup[$accKeyNorm])) {
                    $accountRelLookup[$accKeyNorm] = trim((string)$relLookup);
                }
            }
        }

        $taxHierarchyAccounts = array();
        $taxHierarchyCurrentCode = "";
        if ($taxHierarchyEnabled && sizeof($taxHierarchyCategories) > 0) {
            foreach ($taxHierarchyCategories as $catKey => $catMeta) {
                $catLabel = isset($catMeta["label"]) ? trim((string)$catMeta["label"]) : $catKey;
                $catNote = isset($catMeta["note"]) ? trim((string)$catMeta["note"]) : "";
                $catPosition = isset($catMeta["position"]) ? strtolower(trim((string)$catMeta["position"])) : "debet";
                if ($catPosition != "kredit") {
                    $catPosition = "debet";
                }
                if (!isset($taxHierarchyTotals["category_totals"][$catKey])) {
                    $taxHierarchyTotals["category_totals"][$catKey] = array(
                        "label" => $catLabel,
                        "saldo" => 0,
                        "account_count" => 0,
                        "active_account_count" => 0,
                    );
                }

                $catAccounts = isset($catMeta["accounts"]) && is_array($catMeta["accounts"]) ? $catMeta["accounts"] : array();
                if (sizeof($catAccounts) == 0) {
                    continue;
                }
                foreach ($catAccounts as $rekCodeRaw => $rekMetaRaw) {
                    $rekCode = trim((string)$rekCodeRaw);
                    if ($rekCode == "") {
                        continue;
                    }
                    $rekMeta = is_array($rekMetaRaw) ? $rekMetaRaw : array();
                    $rekLabel = isset($rekMeta["label"]) ? trim((string)$rekMeta["label"]) : $rekCode;
                    $rekNote = isset($rekMeta["note"]) ? trim((string)$rekMeta["note"]) : "";
                    $routeRekening = isset($rekMeta["route_rekening"]) ? trim((string)$rekMeta["route_rekening"]) : $rekCode;
                    if ($routeRekening == "") {
                        $routeRekening = $rekCode;
                    }

                    $rekAliases = array($rekCode, $routeRekening);
                    if (isset($rekMeta["aliases"]) && is_array($rekMeta["aliases"])) {
                        foreach ($rekMeta["aliases"] as $rekAliasTmp) {
                            $rekAliasTmp = trim((string)$rekAliasTmp);
                            if ($rekAliasTmp != "") {
                                $rekAliases[] = $rekAliasTmp;
                            }
                        }
                    }
                    if (isset($accountAliases[$rekCode]) && trim((string)$accountAliases[$rekCode]) != "") {
                        $rekAliases[] = trim((string)$accountAliases[$rekCode]);
                    }
                    if (isset($accountAliases[$routeRekening]) && trim((string)$accountAliases[$routeRekening]) != "") {
                        $rekAliases[] = trim((string)$accountAliases[$routeRekening]);
                    }
                    $rekAliases = array_values(array_unique($rekAliases));

                    $resolvedRel = isset($rekMeta["rel"]) ? trim((string)$rekMeta["rel"]) : "";
                    if ($resolvedRel == "") {
                        foreach ($rekAliases as $rekAliasLookup) {
                            $rekAliasNorm = strtolower(trim((string)$rekAliasLookup));
                            if ($rekAliasNorm != "" && isset($accountRelLookup[$rekAliasNorm]) && trim((string)$accountRelLookup[$rekAliasNorm]) != "") {
                                $resolvedRel = trim((string)$accountRelLookup[$rekAliasNorm]);
                                break;
                            }
                        }
                    }
                    if ($resolvedRel == "" && isset($rekMeta["fallback_rel"])) {
                        $resolvedRel = trim((string)$rekMeta["fallback_rel"]);
                    }

                    $routeEnabled = true;
                    if (isset($rekMeta["route_enabled"])) {
                        $routeEnabled = (bool)$rekMeta["route_enabled"];
                    }
                    if ($resolvedRel == "") {
                        $routeEnabled = false;
                    }
                    if ($routeEnabled) {
                        if (!isset($accountBalanceColumnsAll[$resolvedRel])) {
                            $routeEnabled = false;
                        }
                        else {
                            $mdlCandidate = "Com" . $resolvedRel;
                            $mdlPath = APPPATH . "models/Coms/" . $mdlCandidate . ".php";
                            if (!file_exists($mdlPath)) {
                                $routeEnabled = false;
                            }
                        }
                    }

                    $status = isset($rekMeta["status"]) ? strtolower(trim((string)$rekMeta["status"])) : "";
                    if ($status == "") {
                        $status = $routeEnabled ? "active" : "planned";
                    }
                    if ($status == "planned") {
                        $routeEnabled = false;
                    }

                    $positionDefault = isset($rekMeta["position"]) ? strtolower(trim((string)$rekMeta["position"])) : $catPosition;
                    if ($positionDefault != "kredit") {
                        $positionDefault = "debet";
                    }

                    $taxHierarchyAccounts[$rekCode] = array(
                        "label" => $rekLabel,
                        "note" => $rekNote,
                        "route_rekening" => $routeRekening,
                        "aliases" => $rekAliases,
                        "rel" => $resolvedRel,
                        "route_enabled" => $routeEnabled,
                        "status" => $status,
                        "position" => $positionDefault,
                        "category_key" => $catKey,
                        "category_label" => $catLabel,
                        "category_note" => $catNote,
                    );

                    $taxHierarchyTotals["category_totals"][$catKey]["account_count"]++;
                    if ($status == "planned") {
                        $taxHierarchyTotals["planned_account_count"]++;
                    }
                    else {
                        $taxHierarchyTotals["active_account_count"]++;
                        $taxHierarchyTotals["category_totals"][$catKey]["active_account_count"]++;
                    }

                    foreach ($rekAliases as $rekAlias) {
                        if (strtolower(trim((string)$rekAlias)) == $rekNameNorm) {
                            if ($taxHierarchyCurrentCode == "") {
                                $taxHierarchyCurrentCode = $rekCode;
                            }
                            break;
                        }
                    }
                }
            }
        }

        if ($taxHierarchyCurrentCode != "") {
            $showTaxHierarchy = true;
            $taxHierarchyCurrent = $taxHierarchyCurrentCode;
            $taxHierarchyQuery = $pageQuery;
            if ($q != "") {
                $taxHierarchyQuery["q"] = $q;
            }
            foreach ($taxHierarchyAccounts as $rekCode => $rekMeta) {
                $taxUrl = "#";
                if (isset($rekMeta["route_enabled"]) && $rekMeta["route_enabled"] && isset($rekMeta["rel"]) && trim((string)$rekMeta["rel"]) != "") {
                    $taxUrl = base_url() . get_class($this) . "/" . $this->uri->segment(2) . "/" . trim((string)$rekMeta["rel"]) . "/" . rawurlencode($rekMeta["route_rekening"]) . "?" . http_build_query($taxHierarchyQuery);
                }
                $taxHierarchyLinks[$rekCode] = array(
                    "label" => isset($rekMeta["label"]) ? $rekMeta["label"] : $rekCode,
                    "note" => isset($rekMeta["note"]) ? $rekMeta["note"] : "",
                    "url" => $taxUrl,
                    "rel" => isset($rekMeta["rel"]) ? $rekMeta["rel"] : "",
                    "route_rekening" => isset($rekMeta["route_rekening"]) ? $rekMeta["route_rekening"] : $rekCode,
                    "route_enabled" => isset($rekMeta["route_enabled"]) ? (bool)$rekMeta["route_enabled"] : false,
                    "status" => isset($rekMeta["status"]) ? $rekMeta["status"] : "active",
                    "position" => isset($rekMeta["position"]) ? $rekMeta["position"] : "debet",
                    "category_key" => isset($rekMeta["category_key"]) ? $rekMeta["category_key"] : "",
                    "category_label" => isset($rekMeta["category_label"]) ? $rekMeta["category_label"] : "",
                    "category_note" => isset($rekMeta["category_note"]) ? $rekMeta["category_note"] : "",
                    "saldo" => 0,
                    "count" => 0,
                    "cabang_count" => 0,
                );
            }
            $taxHierarchyNote = "Mode pajak aktif: struktur aset pajak, utang pajak, dan beban pajak ditampilkan dalam satu panel rekonsiliasi.";
        }

        if ($showUangMukaHierarchy && sizeof($uangMukaHierarchyAccounts) > 0) {
            $uangMukaHierarchyQuery = $pageQuery;
            if ($q != "") {
                $uangMukaHierarchyQuery["q"] = $q;
            }
            foreach ($uangMukaHierarchyAccounts as $rekCode => $rekMeta) {
                $rekLabel = isset($rekMeta["label"]) ? trim((string)$rekMeta["label"]) : $rekCode;
                $rekNote = isset($rekMeta["note"]) ? trim((string)$rekMeta["note"]) : "";
                $uangMukaHierarchyLinks[$rekCode] = array(
                    "label" => $rekLabel,
                    "note" => $rekNote,
                    "url" => base_url() . get_class($this) . "/" . $this->uri->segment(2) . "/RekeningPembantuUangMuka/" . rawurlencode($rekCode) . "?" . http_build_query($uangMukaHierarchyQuery),
                    "saldo" => 0,
                    "count" => 0,
                );
            }
            if ($uangMukaMode == "pivot") {
                $uangMukaHierarchyNote = "Mode pivot uang muka aktif: analisa dimensi supplier/reference/cabang terhadap saldo open.";
            }
        }

        $serverDefault = ($relName == "RekeningPembantuProduk") ? 1 : 0;
        $server_side = $this->input->get("server", TRUE);
        $server_side = is_numeric($server_side) ? (int)$server_side : $serverDefault;
        $server_side = ($server_side === 1) ? 1 : 0;
        $server_json = $this->input->get("json", TRUE);
        $server_json = is_numeric($server_json) ? (int)$server_json : 0;
        $server_json = ($server_json === 1) ? 1 : 0;
        if ($server_json === 1) {
            $server_side = 1;
        }
        if ($server_side === 0) {
            $server_json = 0;
        }
        if ($showUangMukaHierarchy && $uangMukaMode == "pivot") {
            $server_side = 0;
            $server_json = 0;
        }
        if ($showUangMukaHierarchy && !$server_json) {
            $uangMukaPivotSourceTable = isset($uangMukaPivotConfig["source_table"]) ? trim((string)$uangMukaPivotConfig["source_table"]) : "_rek_pembantu_uang_muka_reference_cache";
            $hierarchySummarySpec = $this->buildUangMukaHierarchySummary(array(
                "accounts" => $uangMukaHierarchyAccounts,
                "cabang_id" => $cabangID,
                "selected_periode" => $selectedPeriode,
                "selected_thn" => $selectedThn,
                "selected_bln" => $selectedBln,
                "selected_date" => $selectedDate,
                "source_table" => $uangMukaPivotSourceTable,
            ));
            $uangMukaHierarchySummary = isset($hierarchySummarySpec["summary"]) && is_array($hierarchySummarySpec["summary"]) ? $hierarchySummarySpec["summary"] : array();
            $uangMukaHierarchyTotals = isset($hierarchySummarySpec["totals"]) && is_array($hierarchySummarySpec["totals"]) ? $hierarchySummarySpec["totals"] : $uangMukaHierarchyTotals;

            if (sizeof($uangMukaHierarchyLinks) > 0) {
                foreach ($uangMukaHierarchyLinks as $rekCode => $rekSpec) {
                    $uangMukaHierarchyLinks[$rekCode]["saldo"] = isset($uangMukaHierarchySummary[$rekCode]["saldo"]) ? (float)$uangMukaHierarchySummary[$rekCode]["saldo"] : 0;
                    $uangMukaHierarchyLinks[$rekCode]["count"] = isset($uangMukaHierarchySummary[$rekCode]["count"]) ? (int)$uangMukaHierarchySummary[$rekCode]["count"] : 0;
                }
            }
        }
        //        if (ipadd() == "202.65.117.72") {
        //            $server_side=1;
        //        }
//
        $mdlName = "Com" . $relName;

        if ($showUangMukaHierarchy && $uangMukaMode == "pivot") {
            $periode_txt = "";
            switch ($selectedPeriode) {
                case "tahunan":
                    $periode_txt = "Tahun " . $selectedThn;
                    break;
                case "bulanan":
                    $periode_txt = date("F Y", mktime(0, 0, 0, $selectedBln, 1, $selectedThn));
