                    $bankCodeName = trim((string)$bankCodeRaw);
                    if ($bankCodeName == "") {
                        continue;
                    }
                    $bankCodeName = preg_replace('/^[0-9]+/', '', $bankCodeName);
                    $bankCodeName = preg_replace('/^[\-\s]+/', '', $bankCodeName);
                    $bankCodeName = trim((string)$bankCodeName);
                    if ($bankCodeName != "") {
                        $bankCodeMap[(string)$bankCodeKey] = $bankCodeName;
                    }
