                $leftVal = isset($left->$sortBy) ? $left->$sortBy : "";
                $rightVal = isset($right->$sortBy) ? $right->$sortBy : "";

                if (is_numeric($leftVal) && is_numeric($rightVal)) {
                    $leftNum = (float)$leftVal;
                    $rightNum = (float)$rightVal;
                    if ($leftNum == $rightNum) {
                        $cmp = 0;
                    }
                    elseif ($leftNum < $rightNum) {
                        $cmp = -1;
                    }
                    else {
                        $cmp = 1;
                    }
                }
                else {
                    $cmp = strnatcasecmp((string)$leftVal, (string)$rightVal);
                    if ($cmp < 0) {
                        $cmp = -1;
                    }
                    elseif ($cmp > 0) {
                        $cmp = 1;
                    }
                    else {
                        $cmp = 0;
                    }
                }

                return $cmp * $sortDirection;
            });
        }

