        $calcAgeDayAsOf = function ($dateValue) use ($selectedPeriodEndDate) {
            $dateValue = trim((string)$dateValue);
            if ($dateValue == "") {
                return 0;
            }
            if (preg_match('/^(\d{2})(\d{2})(\d{2})\-\d{6}$/', $dateValue, $stampMatch)) {
                $dateValue = "20" . $stampMatch[1] . "-" . $stampMatch[2] . "-" . $stampMatch[3];
            }
            $dateTs = strtotime($dateValue);
            if ($dateTs === FALSE) {
                return 0;
            }
            $asOfTs = strtotime($selectedPeriodEndDate . " 23:59:59");
            if ($asOfTs === FALSE) {
                $asOfTs = time();
            }
            return (int)floor(($asOfTs - $dateTs) / 86400);
        };
