                    if ($defPositionKey != "" && isset($row->$defPositionKey) && is_numeric($row->$defPositionKey)) {
                        $openBalanceRaw = (float)$row->$defPositionKey;
                    }
                    elseif ($positionKey != "" && isset($row->$positionKey) && is_numeric($row->$positionKey)) {
