                    }
                    else {
                        $openBalanceRaw = 0;
                    }

                    // Samakan patokan dengan tampilan UI saldo (format tanpa desimal).
                    // Jika di UI tampil "0", due/aging harus disembunyikan.
                    $openBalanceDisplay = (float)number_format((float)$openBalanceRaw, 0, '.', '');
                    $hasOpenBalance = (abs($openBalanceDisplay) > 0);
