                                    continue;
                                }

                                // format stamp cache lama: yymmdd-His
                                if (preg_match('/^(\d{2})(\d{2})(\d{2})\-\d{6}$/', $fallbackDateRaw, $stampMatch)) {
                                    $fallbackStampDate = "20" . $stampMatch[1] . "-" . $stampMatch[2] . "-" . $stampMatch[3];
                                    $fallbackStampTs = strtotime($fallbackStampDate);
                                    if ($fallbackStampTs !== FALSE) {
                                        $fallbackPostingDate = date("Y-m-d", $fallbackStampTs);
                                        break;
                                    }
                                }

                                $fallbackDateTs = strtotime($fallbackDateRaw);
                                if ($fallbackDateTs !== FALSE) {
                                    $fallbackPostingDate = date("Y-m-d", $fallbackDateTs);
                                    break;
                                }
                            }

                            $fallbackGrnCandidates = array(
                                "grn_date",
                                "receive_date",
                                "received_date",
                                "terima_barang_date",
                                "tgl_grn",
                                "tgl_terima",
                                "dtime_grn",
                                "dtime_receive",
                            );
