                                    continue;
                                }
                                $fallbackGrnRaw = trim((string)$row->$fallbackGrnField);
                                if ($fallbackGrnRaw == "") {
                                    continue;
                                }

                                // format stamp cache lama: yymmdd-His
                                if (preg_match('/^(\d{2})(\d{2})(\d{2})\-\d{6}$/', $fallbackGrnRaw, $stampMatchGrn)) {
                                    $fallbackStampDateGrn = "20" . $stampMatchGrn[1] . "-" . $stampMatchGrn[2] . "-" . $stampMatchGrn[3];
                                    $fallbackStampTsGrn = strtotime($fallbackStampDateGrn);
                                    if ($fallbackStampTsGrn !== FALSE) {
                                        $fallbackGrnDate = date("Y-m-d", $fallbackStampTsGrn);
                                        break;
                                    }
                                }

                                $fallbackDateTsGrn = strtotime($fallbackGrnRaw);
                                if ($fallbackDateTsGrn !== FALSE) {
                                    $fallbackGrnDate = date("Y-m-d", $fallbackDateTsGrn);
                                    break;
                                }
                            }

