                                $fallbackAgingPostingDay = $calcAgeDayAsOf($fallbackPostingDate);
                                $fallbackAgingPostingValue = $fallbackAgingPostingDay > 0 ? $fallbackAgingPostingDay : "0";
                                if (isset($advHeader['aging_posting'])) {
