                                    }

                                    $fallbackDueBaseDate = ($fallbackGrnDate != "") ? $fallbackGrnDate : $fallbackPostingDate;
                                    $fallbackDueDate = $fallbackDueBaseDate;
                                    if ($fallbackDueBaseDate != "") {
                                        $fallbackDueTs = strtotime($fallbackDueBaseDate . " +" . $supplierDueDays . " day");
