            }

            $persediaanBrandBaseQuery = $persediaanBrandQueryCurrent;
            if (isset($persediaanBrandBaseQuery["merek"])) {
                unset($persediaanBrandBaseQuery["merek"]);
            }
            $persediaanBrandClearUrl = $thisPath . "?" . http_build_query($persediaanBrandBaseQuery);

            $extractPersediaanBrand = function ($rowData) {
                if (!is_array($rowData)) {
                    return "";
                }
                $brandFields = array("merek_nama", "merek", "brand", "merk");
                foreach ($brandFields as $brandField) {
                    if (!isset($rowData[$brandField])) {
                        continue;
                    }
                    $brandVal = trim((string)$rowData[$brandField]);
                    if ($brandVal != "") {
                        return $brandVal;
                    }
                }
                return "";
            };

            $persediaanBrandAgg = array();
            $parseNumericVal = function ($valueRaw) {
                if (is_int($valueRaw) || is_float($valueRaw)) {
                    return (float)$valueRaw;
                }
                if (is_bool($valueRaw) || is_array($valueRaw) || is_object($valueRaw)) {
                    return NULL;
                }
                $valueStr = trim((string)$valueRaw);
                if ($valueStr == "") {
                    return NULL;
                }
                if (is_numeric($valueStr)) {
                    return (float)$valueStr;
                }

                $valueNorm = str_replace(" ", "", $valueStr);
                $valueNorm = str_replace("Rp", "", $valueNorm);
                if (strpos($valueNorm, ",") !== false && strpos($valueNorm, ".") !== false) {
                    // format lokal: 1.234,56 -> 1234.56
                    $valueNorm = str_replace(".", "", $valueNorm);
                    $valueNorm = str_replace(",", ".", $valueNorm);
                }
                elseif (strpos($valueNorm, ",") !== false && strpos($valueNorm, ".") === false) {
                    // format lokal sederhana: 12,5 -> 12.5
                    $valueNorm = str_replace(",", ".", $valueNorm);
                }
                else {
                    // antisipasi separator ribuan: 1,234.56
                    $valueNorm = str_replace(",", "", $valueNorm);
                }
                if (is_numeric($valueNorm)) {
                    return (float)$valueNorm;
                }
                return NULL;
            };
            $pickNumericByKeys = function ($rowData, $candidateKeys, $fallbackVal) use ($parseNumericVal) {
                if (!is_array($rowData) || !is_array($candidateKeys)) {
                    return $fallbackVal;
                }
                foreach ($candidateKeys as $fieldKey) {
                    $fieldKey = trim((string)$fieldKey);
                    if ($fieldKey == "" || !array_key_exists($fieldKey, $rowData)) {
                        continue;
                    }
                    $parsedVal = $parseNumericVal($rowData[$fieldKey]);
                    if ($parsedVal !== NULL) {
                        return $parsedVal;
                    }
                }
                return $fallbackVal;
            };
            $saldoTotalKeys = array(
                "total_debet",
                "debet",
                "ng_debet",
                "wo_debet",
                "kredit",
            );
            $persediaanTotalAll = 0;
            foreach ($items as $rowData) {
                $persediaanTotalAll += $pickNumericByKeys($rowData, $saldoTotalKeys, 0);
            }
            if ($persediaanTotalAll > 0) {
                $persediaanHierarchyTotals["all"] = $persediaanTotalAll;
            }
            $qtyCandidateKeys = array(
                "total_qty_debet",
                "qty_debet",
                "total_qty_kredit",
                "qty_kredit",
                "saldo_qty_berjalan",
                "qty",
            );
            $saldoCandidateKeys = array(
                "total_debet",
                "debet",
                "total_kredit",
                "kredit",
                "saldo_berjalan",
                "saldo",
                "nilai",
            );
            $defPositionNorm = strtolower(trim((string)$defPosition));
            if ($defPositionNorm == "debet" || $defPositionNorm == "kredit") {
                array_unshift($qtyCandidateKeys, "total_qty_" . $defPositionNorm, "qty_" . $defPositionNorm);
                array_unshift($saldoCandidateKeys, "total_" . $defPositionNorm, $defPositionNorm);
            }

            foreach ($items as $rowIdx => $rowData) {
                if (!is_array($rowData)) {
                    continue;
                }
                $brandLabel = $extractPersediaanBrand($rowData);
                if ($brandLabel == "") {
                    $brandLabel = "(Tanpa Merek)";
                }
                $brandNorm = strtolower($brandLabel);
                if (!isset($persediaanBrandAgg[$brandNorm])) {
                    $persediaanBrandAgg[$brandNorm] = array(
                        "label" => $brandLabel,
                        "count" => 0,
                        "qty" => 0,
                        "saldo" => 0,
                        "item_map" => array(),
                    );
                }

                $rowUniqueKey = "";
                if (isset($rowData["pId"])) {
                    $rowPid = trim((string)$rowData["pId"]);
                    if ($rowPid != "" && $rowPid != "0") {
                        $rowUniqueKey = "pid:" . $rowPid;
                    }
                }
                if ($rowUniqueKey == "" && isset($rowData["extern_id"])) {
                    $rowExternID = trim((string)$rowData["extern_id"]);
                    if ($rowExternID != "") {
                        $rowUniqueKey = "extern:" . $rowExternID;
                    }
                }
                if ($rowUniqueKey == "") {
                    $rowUniqueKey = "row:" . $rowIdx;
                }
                if (!isset($persediaanBrandAgg[$brandNorm]["item_map"][$rowUniqueKey])) {
                    $persediaanBrandAgg[$brandNorm]["item_map"][$rowUniqueKey] = 1;
                    $persediaanBrandAgg[$brandNorm]["count"]++;
                }

                $qtyVal = $pickNumericByKeys($rowData, $qtyCandidateKeys, 0);
                $saldoVal = $pickNumericByKeys($rowData, $saldoCandidateKeys, 0);
                $persediaanBrandAgg[$brandNorm]["qty"] += $qtyVal;
                $persediaanBrandAgg[$brandNorm]["saldo"] += $saldoVal;
            }

            if ($merekFilterNorm != "") {
                $filteredItems = array();
                foreach ($items as $rowData) {
                    $brandLabel = $extractPersediaanBrand($rowData);
                    if ($brandLabel == "") {
                        $brandLabel = "(Tanpa Merek)";
                    }
                    if (strtolower($brandLabel) == $merekFilterNorm) {
                        $filteredItems[] = $rowData;
                    }
                }
                $items = $filteredItems;
                if (sizeof($items_blok) > 0) {
                    $items_blok = array();
                }
            }

            if (sizeof($persediaanBrandAgg) > 0) {
                uasort($persediaanBrandAgg, function ($a, $b) {
                    if ($a["count"] == $b["count"]) {
                        return strcmp((string)$a["label"], (string)$b["label"]);
                    }
                    return ($a["count"] > $b["count"]) ? -1 : 1;
