                        $this->db->where(array(
                            "thn" => $selectedThn,
                        ));
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalancePeriode($taxRekening, "", "tahunan");
                        break;
                    case "bulanan":
                        $this->db->where(array(
                            "thn" => $selectedThn,
                            "bln<=" => $selectedBln,
                        ));
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalancePeriode($taxRekening, "", "bulanan");
                        break;
                    case "harian":
                        $this->db->where("fulldate<=", $selectedDate);
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalancePeriode($taxRekening, "", "harian");
                        break;
                    default:
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalances($taxRekening);
                        break;
                }

                if (sizeof($tmp_hierarchy_0) > 0) {
                    foreach ($tmp_hierarchy_0 as $tmp_hierarchy_spec) {
                        $tmp_hierarchy[] = $tmp_hierarchy_spec;
                    }
                }

                $saldoPosisi = detectRekDefaultPosition($taxRekening);
                if ($saldoPosisi != "debet" && $saldoPosisi != "kredit") {
                    $saldoPosisi = isset($rekSpec["position"]) ? strtolower(trim((string)$rekSpec["position"])) : "debet";
                    if ($saldoPosisi != "kredit") {
                        $saldoPosisi = "debet";
                    }
                }
                $saldoPosisiLawan = ($saldoPosisi == "debet") ? "kredit" : "debet";
                $saldoValue = 0;
                $entryCount = 0;
                $entityMap = array();
                $cabangMap = array();
                if (sizeof($tmp_hierarchy) > 0) {
                    foreach ($tmp_hierarchy as $tmp_hierarchy_spec) {
                        $entityId = isset($tmp_hierarchy_spec->extern_id) ? trim((string)$tmp_hierarchy_spec->extern_id) : "";
                        if ($entityId != "") {
                            if (!isset($entityMap[$entityId])) {
                                $entityMap[$entityId] = 1;
                                $entryCount++;
                                $entityAgg[$entityId] = 1;
                            }
                        }
                        else {
                            $entryCount++;
                        }

                        $cabangTmp = isset($tmp_hierarchy_spec->cabang_id) ? (string)$tmp_hierarchy_spec->cabang_id : "";
                        if ($cabangTmp != "") {
                            $cabangMap[$cabangTmp] = 1;
                            $cabangAgg[$cabangTmp] = 1;
                        }

                        $saldoMain = isset($tmp_hierarchy_spec->$saldoPosisi) ? (float)$tmp_hierarchy_spec->$saldoPosisi : 0;
                        $saldoLawan = isset($tmp_hierarchy_spec->$saldoPosisiLawan) ? (float)$tmp_hierarchy_spec->$saldoPosisiLawan : 0;
                        if ($saldoLawan > 0) {
                            $saldoMain = $saldoLawan * -1;
                        }
                        $saldoValue += $saldoMain;
                    }
                }

                $taxHierarchySummary[$rekCode] = array(
                    "saldo" => $saldoValue,
                    "count" => $entryCount,
                    "cabang_count" => sizeof($cabangMap),
                );
                $taxHierarchyTotals["all"] += $saldoValue;
                $taxCategoryKey = isset($rekSpec["category_key"]) ? trim((string)$rekSpec["category_key"]) : "";
                if ($taxCategoryKey != "" && isset($taxHierarchyTotals["category_totals"][$taxCategoryKey])) {
                    $taxHierarchyTotals["category_totals"][$taxCategoryKey]["saldo"] += $saldoValue;
                }
            }

            $taxHierarchyTotals["entity_count"] = sizeof($entityAgg);
            $taxHierarchyTotals["cabang_count"] = sizeof($cabangAgg);
            foreach ($taxHierarchyLinks as $rekCode => $rekSpec) {
                $taxHierarchyLinks[$rekCode]["saldo"] = isset($taxHierarchySummary[$rekCode]["saldo"]) ? $taxHierarchySummary[$rekCode]["saldo"] : 0;
                $taxHierarchyLinks[$rekCode]["count"] = isset($taxHierarchySummary[$rekCode]["count"]) ? $taxHierarchySummary[$rekCode]["count"] : 0;
                $taxHierarchyLinks[$rekCode]["cabang_count"] = isset($taxHierarchySummary[$rekCode]["cabang_count"]) ? $taxHierarchySummary[$rekCode]["cabang_count"] : 0;
            }
        }

        if ($showUangMukaHierarchy && $uangMukaMode == "hierarchy" && !$server_json) {
            $uangMukaHierarchySummary = array();
            $uangMukaHierarchyTotals = array(
                "all" => 0,
                "supplier_count" => 0,
            );
            $supplierAgg = array();

            foreach ($uangMukaHierarchyAccounts as $rekCode => $rekMeta) {
                $this->db->reset_query();
                $comHierarchy = new $mdlName();
                $comHierarchy->addFilter("cabang_id='$cabangID'");
                if ($getExtern2ID != NULL) {
                    $comHierarchy->addFilter("extern2_id='$getExtern2ID'");
                }
                if ($getExternID != NULL) {
                    $comHierarchy->addFilter("extern_id='$getExternID'");
                }

                $tmp_hierarchy = array();
                switch ($selectedPeriode) {
                    case "full":
                        $this->db->where(array(
                            "thn" => $currentYear,
                        ));
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalancePeriode($rekCode, "", "tahunan");
                        if (sizeof($tmp_hierarchy_0) == 0) {
                            // fallback saat cache tahunan belum terbentuk
                            $tmp_hierarchy_0 = $comHierarchy->fetchBalances($rekCode);
                        }
                        break;
                    case "tahunan":
                        $this->db->where(array(
                            "thn" => $selectedThn,
                        ));
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalancePeriode($rekCode, "", "tahunan");
                        break;
                    case "bulanan":
                        $this->db->where(array(
                            "thn" => $selectedThn,
                            "bln<=" => $selectedBln,
                        ));
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalancePeriode($rekCode, "", "bulanan");
                        break;
                    case "harian":
                        $this->db->where("fulldate<=", $selectedDate);
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalancePeriode($rekCode, "", "harian");
                        break;
                    default:
                        $tmp_hierarchy_0 = $comHierarchy->fetchBalances($rekCode);
                        break;
                }

                if (sizeof($tmp_hierarchy_0) > 0) {
                    foreach ($tmp_hierarchy_0 as $tmp_hierarchy_spec) {
                        $tmp_hierarchy[$tmp_hierarchy_spec->extern_id] = $tmp_hierarchy_spec;
                    }
                }

                $saldoPosisi = detectRekDefaultPosition($rekCode);
                $saldoPosisiLawan = ($saldoPosisi == "debet") ? "kredit" : "debet";
                $saldoValue = 0;
                $supplierCount = 0;
                if (sizeof($tmp_hierarchy) > 0) {
                    foreach ($tmp_hierarchy as $tmp_hierarchy_spec) {
                        $supplierId = isset($tmp_hierarchy_spec->extern_id) ? (int)$tmp_hierarchy_spec->extern_id : 0;
                        if ($supplierId > 0 && !isset($supplierAgg[$supplierId])) {
                            $supplierAgg[$supplierId] = 1;
                        }
                        if ($supplierId > 0) {
                            $supplierCount++;
                        }

                        $saldoMain = isset($tmp_hierarchy_spec->$saldoPosisi) ? (float)$tmp_hierarchy_spec->$saldoPosisi : 0;
                        $saldoLawan = isset($tmp_hierarchy_spec->$saldoPosisiLawan) ? (float)$tmp_hierarchy_spec->$saldoPosisiLawan : 0;
                        if ($saldoLawan > 0) {
                            $saldoMain = $saldoLawan * -1;
                        }
                        $saldoValue += $saldoMain;
                    }
                }

                $uangMukaHierarchySummary[$rekCode] = array(
                    "saldo" => $saldoValue,
                    "count" => $supplierCount,
                );
                $uangMukaHierarchyTotals["all"] += $saldoValue;
            }

            $uangMukaHierarchyTotals["supplier_count"] = sizeof($supplierAgg);

            if (sizeof($uangMukaHierarchyLinks) > 0) {
                foreach ($uangMukaHierarchyLinks as $rekCode => $rekSpec) {
                    $uangMukaHierarchyLinks[$rekCode]["saldo"] = isset($uangMukaHierarchySummary[$rekCode]["saldo"]) ? $uangMukaHierarchySummary[$rekCode]["saldo"] : 0;
                    $uangMukaHierarchyLinks[$rekCode]["count"] = isset($uangMukaHierarchySummary[$rekCode]["count"]) ? $uangMukaHierarchySummary[$rekCode]["count"] : 0;
                }
            }
        }

        $defaultThnKiriman = array(
            "o" => $cabangID,
            "bln" => $selectedBln,
            "periode" => $selectedPeriode,
            "date" => $selectedDate,
        );
        if ($showUangMukaHierarchy) {
            $defaultThnKiriman["mode"] = $uangMukaMode;
            if ($uangMukaMode == "pivot") {
                $defaultThnKiriman["row_dim"] = $uangMukaPivotRowDim;
                $defaultThnKiriman["col_dim"] = $uangMukaPivotColDim;
                $defaultThnKiriman["metric"] = $uangMukaPivotMetric;
            }
        }

        if (isset($_GET['debug_persediaan']) && $_GET['debug_persediaan'] == '1') {
            $debugLinks = array();
            foreach ($persediaanHierarchyLinks as $rekCode => $spec) {
                $debugLinks[$rekCode] = array(
                    "label" => isset($spec["label"]) ? $spec["label"] : $rekCode,
                    "saldo" => isset($spec["saldo"]) ? (float)$spec["saldo"] : 0,
                    "count" => isset($spec["count"]) ? (int)$spec["count"] : 0,
                    "summary_rel" => isset($spec["summary_rel"]) ? $spec["summary_rel"] : "",
                    "query_rekening" => isset($spec["query_rekening"]) ? $spec["query_rekening"] : "",
                    "query_candidates" => isset($spec["query_candidates"]) ? $spec["query_candidates"] : array(),
                );
            }
            $debug = array(
                "periode" => $selectedPeriode,
                "thn" => $selectedThn,
                "bln" => $selectedBln,
                "date" => $selectedDateFull,
                "total" => isset($persediaanHierarchyTotals["all"]) ? (float)$persediaanHierarchyTotals["all"] : 0,
                "item_count" => isset($persediaanHierarchyTotals["item_count"]) ? (int)$persediaanHierarchyTotals["item_count"] : 0,
                "cards" => $debugLinks,
            );
            header("Content-Type: application/json; charset=UTF-8");
            echo json_encode($debug, JSON_PRETTY_PRINT);
            return;
        }

        $data = array(
            "mode" => "saldo",//concat
            //            "mode" => "saldoHereDoc",//heredoc
            "title" => "$rekName_f",
            "server" => $server_side,
