                $trk->setFilters(array());
                $trk->addFilter("transaksi_id in ('" . implode("','", $arrTrIDs) . "')");
                $trkTmp = $trk->lookUpDataRegistries()->result();
                if (sizeof($trkTmp) > 0) {
