                    $date2 = isset($_GET['date2']) ? $_GET['date2'] : date("Y-m-d");
                    break;

            }
            $this->db->order_by("id", "DESC");
            $this->db->where("fulldate>='" . $date1 . "'");
            $this->db->where("fulldate<='" . $date2 . "'");
            $subTitle_date = lgTranslateTime($date1) . " - " . lgTranslateTime($date2);
        }
