                $saldo_qty_berjalan += ($temX->qty_debet - $temX->qty_kredit);
                $saldo_value_berjalan += ($temX->debet - $temX->kredit);
                $saldoBerjalan[$temX->id]['qty'] = $saldo_qty_berjalan;
