        $arrDecode = array("ids_his", "counters");
        $jenisAliases = arrCodeAliasing($cabangID);
        $arrTransData = array();
        $trDatasLink = array();
        $arrTrIDs = array();
        $regDatas = array();
        //        $arrDataTr = array(
        //            "customers_id",
        //            "customers_nama",
        //            "suppliers_id",
        //            "suppliers_nama",
        //            "oleh_id",
        //            "oleh_nama",
        //            "jenis_master",
        //        );
        $listId = implode("','", $tmpTrIds);
        if (strlen($listId) > 3) {
            $tr->setFilters(array());
            $tr->addFilter("id in ('" . $listId . "')");
