        $getExtern2ID = isset($_GET['ext2_id']) && strlen($_GET['ext2_id']) ? $_GET['ext2_id'] : NULL;
        $getMainExtern2ID = isset($_GET['main_ext2_id']) && strlen($_GET['main_ext2_id']) ? $_GET['main_ext2_id'] : NULL;
