            }
            $mdlResult = $mdl->$balConfig['pairedModel']['mdlMethod']()->result();
            //            cekHere($this->db->last_query());
            //            arrPrint($mdlResult);

            if (sizeof($mdlResult) > 0) {
                foreach ($mdlResult as $rSpec) {
                    //                    arrPrintWebs($rSpec);
                    foreach ($balConfig['pairedModel']['fieldName'] as $key => $val) {
