                        }
                        if ($row->qty_kredit > 0) {
                            $row->qty_debet = $row->qty_kredit * -1;
                            $row->qty_kredit = 0;
                        }
                        break;
                    case "kredit":
                        if ($row->debet > 0) {
                            $row->kredit = $row->debet * -1;
                            $row->debet = 0;
                        }
                        if ($row->qty_debet > 0) {
